import { Component, OnDestroy, OnInit } from '@angular/core';
import { AccountingService } from '../accounting.service';
import { Subscription } from 'rxjs';
import { TreeNode } from 'primeng/api';
import { FormControl, FormGroup, Validators } from '@angular/forms';

@Component({
    selector: 'app-chart-of-accounts',
    templateUrl: './chart-of-accounts.component.html',
    styleUrl: './chart-of-accounts.component.scss',
})
export class ChartOfAccountsComponent implements OnInit, OnDestroy {
    constructor(private accountingService: AccountingService) {}

    subscriptions = new Subscription();
    mainAccounts;
    subCategories;

    selectedChartOfAccounts;

    selectedCategory;
    selectedAccount;
    accountDialogVisible = false;
    dialogMode;

    formSubmited = false;

    account_type_options = [
        'ASSETS',
        'LIABILITIES',
        'ASSETS/ LIABILITIES',
        'EQUITY',
        'INCOME',
        'EXPENSES',
    ];

    ngOnInit(): void {
        this.subscriptions.add(
            this.accountingService.mainAccounts.subscribe((res) => {
                this.mainAccounts = res;
            })
        );
        this.subscriptions.add(
            this.accountingService.selectedChartOfAccounts.subscribe((res) => {
                this.selectedChartOfAccounts = res;
                if (this.selectedAccount) {
                    console.log(this.selectedAccount.id, res);

                    const updated_account = res.filter(
                        (account) => account.id === this.selectedAccount.id
                    )[0];

                    this.selectedAccount = updated_account;
                }
            })
        );
        this.subscriptions.add(
            this.accountingService.selectedAccount.subscribe((res) => {
                this.selectedCategory = res;
            })
        );
        this.subscriptions.add(
            this.accountingService.subCategories.subscribe(
                (res) => (this.subCategories = res)
            )
        );
        this.accountingService.accountDialogVisible.subscribe(
            (res) => (this.accountDialogVisible = res)
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    selectAccount() {
        this.accountingService.selectAccount(this.selectedCategory);
        this.selectedAccount = null;
    }

    accountForm = new FormGroup({
        account_number: new FormControl<string>(null, Validators.required),
        english_name: new FormControl<string>(null, Validators.required),
        arabic_name: new FormControl<string>(null),
        // french_name: new FormControl<string>(null),
        account_type: new FormControl<string>(null),
        category_number: new FormControl<string>(null, Validators.required),
        sub_category_number: new FormControl<string>(null, Validators.required),
    });
    get sub_category_number() {
        return this.accountForm.get('sub_category_number');
    }
    get english_name() {
        return this.accountForm.get('english_name');
    }
    get account_number() {
        return this.accountForm.get('account_number');
    }

    resetDialog() {
        this.accountForm.reset();
        this.accountingService.accountDialogVisible.next(false);
        this.formSubmited = false;
    }
    saveAccount() {
        this.formSubmited = true;
        if (this.accountForm.invalid) return;
        if (this.dialogMode == 'add') {
            this.accountingService.addAccount(this.accountForm.value);
        } else if (this.dialogMode == 'edit') {
            this.accountingService.editAccount(this.accountForm.value);
        }
    }

    // open account dialog
    openAccountDialog(mode: string) {
        this.dialogMode = mode;
        if (this.dialogMode == 'add') {
            {
                this.accountForm.patchValue({
                    category_number: this.selectedCategory.code,
                });
            }
        } else if (this.dialogMode == 'edit') {
            this.accountForm.patchValue({
                category_number: this.selectedCategory.code,
                sub_category_number: this.selectedAccount.sub_category_number,
                account_number: this.selectedAccount.account_number,
                english_name: this.selectedAccount.english_name,
                arabic_name: this.selectedAccount.arabic_name,
                account_type: this.selectedAccount.account_type,
                // french_name: this.selectedAccount.french_name,
            });
        }
        this.formSubmited = false;
        this.accountingService.accountDialogVisible.next(true);
    }

    getSelectedSubCategory() {
        return this.subCategories.filter(
            (subCategory) => subCategory.code === this.sub_category_number.value
        )[0];
    }
}
