import { Component, inject, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { AccountingService } from '../accounting.service';
import { Subscription } from 'rxjs';
import { FormBuilder, Validators } from '@angular/forms';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { AuxiliaryService } from '../auxiliary.service';
import { DateService } from 'src/app/_services/date.service';
import { StockService } from 'src/app/stock/stock.service';
import { ConfirmationService } from 'primeng/api';
import { DecimalService } from 'src/app/_services/decimal.service';
import { Table } from 'primeng/table';
import { PrintService } from 'src/app/print.service';

@Component({
    selector: 'app-journal-vouchers',
    templateUrl: './journal-vouchers.component.html',
    styleUrl: './journal-vouchers.component.scss',
})
export class JournalVouchersComponent implements OnInit, OnDestroy {
    @ViewChild('dt') voucherTable: Table;

    readonly printService = inject(PrintService);
    constructor(
        private accountingService: AccountingService,
        private auxiliaryService: AuxiliaryService,
        private fb: FormBuilder,
        private dateService: DateService,
        private stockService: StockService,
        private confirmationService: ConfirmationService,
        private decimalService: DecimalService,
    ) {}

    subscriptions = new Subscription();

    chartOfAccounts;

    journalVouchers;
    loading: boolean;
    voucherDialogVisible;

    journalItems = [];
    items = [];
    selectedJournal = {
        totalDebit: 0,
        totalCredit: 0,
    };

    itemsDialogVisible: boolean = false;
    dialogMode: string;

    submitted: boolean = false;
    totalDebit = 0;
    totalCredit = 0;

    credit_input = 0;
    debit_input = 0;

    accounts: AuxiliaryAccount[];

    exchangeRate;

    journalTypes = [
        'Sales Invoice',
        'Payments',
        'Purchase Bill',
        'Miscellaneous',
    ];

    ngOnInit(): void {
        this.subscriptions.add(
            this.accountingService.chartOfAccounts.subscribe((res) => {
                this.chartOfAccounts = res;
            }),
        );
        this.subscriptions.add(
            this.accountingService.loading.subscribe((res) => {
                this.loading = res;
            }),
        );
        this.subscriptions.add(
            this.accountingService.journalVouchers.subscribe((res) => {
                this.journalVouchers = res;
            }),
        );
        this.subscriptions.add(
            this.accountingService.voucherDialogVisible.subscribe((res) => {
                this.voucherDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.auxiliaryService.accounts.subscribe((res) => {
                this.accounts = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.exchangeRate.subscribe((res) => {
                this.exchangeRate = res;
            }),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // search form builder
    searchForm = this.fb.group({
        journal_date: [null],
        journal_number: [null],
        reference_number: [null],
        journal_description: [null],
    });

    // submit search
    submitSearch() {
        this.voucherTable.reset();
        this.accountingService.fetchJournalVouchers(
            this.searchForm.value as any,
        );
    }

    // reset search
    resetSearch() {
        this.voucherTable.reset();
        this.searchForm.reset();
        this.accountingService.fetchJournalVouchers(null);
    }

    // new voucher form
    voucherForm = this.fb.group({
        journal_id: [null],
        journal_number: [null],
        journal_date: [this.dateService.getCurrentDate()],
        reference_number: [''],
        total_value: [0],
        journal_type: [null],
        journal_description: [null],
        exchange_value: [0],
    });

    voucherItemsForm: any = this.fb.group({
        account_id_fk: [null, Validators.required],
        partner_id_fk: [null],
        currency: ['USD'],
        debit: [null, Validators.required],
        credit: [null, Validators.required],
        debit_lbp: [null],
        credit_lbp: [null],
        notes: [null],
    });

    get account_id_fk() {
        return this.voucherItemsForm.get('account_id_fk');
    }
    get currency() {
        return this.voucherItemsForm.get('currency');
    }
    get debit() {
        return this.voucherItemsForm.get('debit');
    }
    get credit() {
        return this.voucherItemsForm.get('credit');
    }
    get debit_lbp() {
        return this.voucherItemsForm.get('debit_lbp');
    }
    get credit_lbp() {
        return this.voucherItemsForm.get('credit_lbp');
    }

    // submit item to table
    submitItem() {
        this.submitted = true;
        if (this.voucherItemsForm.valid) {
            if (
                this.voucherItemsForm.value.debit === 0 &&
                this.voucherItemsForm.value.credit === 0
            ) {
                this.credit.markAsDirty();
                this.debit.markAsDirty();
                this.credit.markAsTouched();
                this.debit.markAsTouched();
                this.debit.setErrors({ customError: true });
                this.credit.setErrors({ customError: true });
                this.voucherItemsForm.markAllAsTouched();
                return;
            }
            if (this.currency.value === 'LBP') {
                this.voucherItemsForm.patchValue({
                    debit:
                        Math.round(
                            (this.voucherItemsForm.value.debit /
                                this.exchangeRate.rate_value) *
                                100,
                        ) / 100,
                    credit:
                        Math.round(
                            (this.voucherItemsForm.value.credit /
                                this.exchangeRate.rate_value) *
                                100,
                        ) / 100,
                    credit_lbp: this.voucherItemsForm.value.credit,
                    debit_lbp: this.voucherItemsForm.value.debit,
                });
            } else {
                this.voucherItemsForm.patchValue({
                    debit_lbp:
                        this.voucherItemsForm.value.debit *
                        this.exchangeRate.rate_value,
                    credit_lbp:
                        this.voucherItemsForm.value.credit *
                        this.exchangeRate.rate_value,
                    credit: this.voucherItemsForm.value.credit,
                    debit: this.voucherItemsForm.value.debit,
                });
            }

            this.submitted = false;
            this.journalItems.push(this.voucherItemsForm.value);
            this.voucherItemsForm.reset({
                currency: 'USD',
            });
            this.debit_input = 0;
            this.credit_input = 0;

            this.calculateTotals();
        }
    }

    calculateTotals() {
        let totalDebit = 0;
        let totalCredit = 0;
        this.journalItems.forEach((element) => {
            // totalDebit += element.debit;
            // totalCredit += element.credit;
            totalDebit = this.decimalService.add(totalDebit, element.debit);
            totalCredit = this.decimalService.add(totalCredit, element.credit);
        });
        this.totalDebit = totalDebit;
        this.totalCredit = totalCredit;
    }

    // reset dialog when closed
    resetDialog() {
        this.journalItems = [];
        this.credit_input = 0;
        this.debit_input = 0;
        this.voucherItemsForm.reset({
            currency: 'USD',
        });
        this.voucherForm.reset({
            journal_date: this.dateService.getCurrentDate(),
        });
        this.accountingService.voucherDialogVisible.next(false);
    }

    // select form input
    select(event) {
        event.select();
    }

    // delete row from table
    deleteRow(index) {
        this.journalItems.splice(index, 1);
        this.calculateTotals();
    }

    // reset debit or credit inputs
    valueChanged(value: string) {
        if (value === 'debit') {
            this.voucherItemsForm.patchValue({
                debit: this.debit_input || 0,
            });
            this.voucherItemsForm.controls['debit'].addValidators([
                Validators.required,
            ]);
            this.voucherItemsForm.controls['credit'].removeValidators([
                Validators.required,
            ]);
            this.voucherItemsForm.controls['debit'].updateValueAndValidity();
            this.voucherItemsForm.controls['credit'].updateValueAndValidity();
            this.credit_input = 0;
            this.voucherItemsForm.patchValue({
                credit: 0,
            });
        } else if (value === 'credit') {
            this.voucherItemsForm.patchValue({
                credit: this.credit_input || 0,
            });
            this.voucherItemsForm.controls['credit'].addValidators([
                Validators.required,
            ]);
            this.voucherItemsForm.controls['debit'].removeValidators([
                Validators.required,
            ]);
            this.voucherItemsForm.controls['debit'].updateValueAndValidity();
            this.voucherItemsForm.controls['credit'].updateValueAndValidity();
            this.debit_input = 0;
            this.voucherItemsForm.patchValue({
                debit: 0,
            });
        }
    }

    // get account name
    getAccountName(id) {
        const account = this.chartOfAccounts.find((acc) => acc.id === id);
        return account?.account_number;
    }
    getAuxiliaryName(id) {
        return this.accounts.find((acc) => acc.account_id === id)?.name;
    }

    // show voucher items dialog
    showVoucherDetails(record) {
        this.items = record.journal_items;
        this.items.forEach((element) => {
            this.selectedJournal.totalDebit += element.debit;
            this.selectedJournal.totalCredit += element.credit;
        });
        // this.selectedJournal
        this.itemsDialogVisible = true;
    }

    // onHide items dialog
    hideItemsDialog() {
        this.itemsDialogVisible = false;
        this.selectedJournal = {
            totalDebit: 0,
            totalCredit: 0,
        };
    }

    // open voucher dialog
    openVoucherDialog(mode: string, selectedRecord) {
        this.dialogMode = mode;
        if (mode === 'add') {
            if (selectedRecord) {
                this.voucherForm.patchValue({
                    // journal_id: selectedRecord.journal_id,
                    journal_number: selectedRecord.journal_number,
                    journal_date: selectedRecord.journal_date,
                    reference_number: selectedRecord.reference_number,
                    total_value: selectedRecord.total_value,
                    journal_type: selectedRecord.journal_type,
                    journal_description: selectedRecord.journal_description,
                    exchange_value: selectedRecord.exchange_value,
                });
                this.journalItems.push(...selectedRecord.journal_items);
                this.calculateTotals();
                this.accountingService.voucherDialogVisible.next(true);
            } else {
                this.accountingService.voucherDialogVisible.next(true);
            }
        } else if (mode === 'edit') {
            this.voucherForm.patchValue({
                journal_id: selectedRecord.journal_id,
                journal_number: selectedRecord.journal_number,
                journal_date: selectedRecord.journal_date,
                reference_number: selectedRecord.reference_number,
                total_value: selectedRecord.total_value,
                journal_type: selectedRecord.journal_type,
                journal_description: selectedRecord.journal_description,
                exchange_value: selectedRecord.exchange_value,
            });
            this.journalItems.push(...selectedRecord.journal_items);
            this.calculateTotals();

            this.accountingService.voucherDialogVisible.next(true);
        }
    }

    // submit voucher
    submitForm() {
        if (this.dialogMode === 'add') {
            this.voucherForm.patchValue({
                total_value: this.totalDebit,
                exchange_value: this.exchangeRate.rate_value,
            });
            if (this.voucherForm.valid && this.journalItems.length > 0) {
                this.confirmationService.confirm({
                    key: 'voucher',
                    message: `Are you sure that you want to continue"?`,
                    header: 'Warning',
                    icon: 'pi pi-exclamation-triangle',
                    acceptButtonStyleClass: 'p-button-danger',
                    rejectButtonStyleClass: 'p-button-secondary',
                    defaultFocus: 'reject',
                    accept: () => {
                        this.accountingService.addJournalVoucher({
                            voucher: { ...this.voucherForm.value },
                            journal_items: this.journalItems,
                        });
                    },
                });
            }
        } else if (this.dialogMode === 'edit') {
            this.voucherForm.patchValue({
                total_value: this.totalDebit,
            });
            this.confirmationService.confirm({
                key: 'voucher',
                message: `Are you sure that you want to continue ?`,
                header: 'Warning',
                icon: 'pi pi-exclamation-triangle',
                acceptButtonStyleClass: 'p-button-danger',
                rejectButtonStyleClass: 'p-button-secondary',
                defaultFocus: 'reject',
                accept: () => {
                    this.accountingService.editJournalVoucher({
                        voucher: { ...this.voucherForm.value },
                        journal_items: this.journalItems,
                    });
                },
            });
        }
    }

    deleteVoucher(record) {
        console.log(record);
        this.confirmationService.confirm({
            key: 'voucher',
            message: `Are you sure that you want to delete this voucher ?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.accountingService.deleteJournalVoucher(record.journal_id);
            },
        });
    }

    print(voucher) {
        console.log(voucher);
        this.printService.printVoucher(voucher);
    }
}
