import { Component, OnDestroy, OnInit } from '@angular/core';
import { AccountingService } from '../accounting.service';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-journal-items',
    templateUrl: './journal-items.component.html',
    styleUrl: './journal-items.component.scss'
})
export class JournalItemsComponent implements OnInit, OnDestroy {

    constructor(private accountingService: AccountingService) { }

    subscriptions = new Subscription()
    journalItems;
    journalItemsTotal;

    ngOnInit(): void {

        this.subscriptions.add(this.accountingService.journalItems.subscribe(res => {
            this.journalItems = res;
            this.accountingService.calculateTotalJournalItems()
        }))

        this.subscriptions.add(this.accountingService.journalItemsTotals.subscribe(res => {
            this.journalItemsTotal = res;
            console.log(res);

        }))
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe()
    }
}
