import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Subscription } from 'rxjs';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { ConfirmationService } from 'primeng/api';

@Component({
    selector: 'app-accounts',
    templateUrl: './accounts.component.html',
    styleUrl: './accounts.component.scss',
})
export class AccountsComponent implements OnInit, OnDestroy {
    constructor(
        private auxiliaryService: AuxiliaryService,
        private confirmationService: ConfirmationService
    ) {}

    subscriptions = new Subscription();
    accounts: AuxiliaryAccount[];
    selectedAccount;
    submitted = false;
    dialogVisible;
    dialogMode;

    auxiliaryOptions = [
        {
            name: 'Yes',
            value: 1,
        },
        {
            name: 'No',
            value: 0,
        },
    ];

    accountsForm = new FormGroup({
        account_id: new FormControl(null),
        name: new FormControl(null, Validators.required),
        address: new FormControl(null),
        phone: new FormControl(null),
        financial_number: new FormControl(null),
        // balance_usd: new FormControl(0),
        is_customer: new FormControl(1),
        is_supplier: new FormControl(0),
        is_bank: new FormControl(0),
        is_employee: new FormControl(0),
        // is_deleted: new FormControl(false),
    });

    get name() {
        return this.accountsForm.get('name');
    }

    ngOnInit(): void {
        this.subscriptions.add(
            this.auxiliaryService.accounts.subscribe((res) => {
                this.accounts = res;
            })
        );
        this.subscriptions.add(
            this.auxiliaryService.dialogVisible.subscribe((res) => {
                this.dialogVisible = res;
            })
        );
        this.subscriptions.add(
            this.auxiliaryService.selectedAccount.subscribe((res) => {
                this.selectedAccount = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    toggleDialog(mode: string) {
        this.dialogMode = mode;
        if (this.dialogMode === 'add') {
            this.auxiliaryService.dialogVisible.next(true);
        } else {
            this.auxiliaryService.selectedAccount.next(this.selectedAccount);
            this.accountsForm.patchValue(this.selectedAccount);
            this.auxiliaryService.dialogVisible.next(true);
        }
    }

    // update the state on row selection
    selectAccount() {
        this.auxiliaryService.selectedAccount.next(this.selectedAccount);
    }

    submitAccount() {
        this.submitted = true;

        if (this.accountsForm.valid) {
            if (this.dialogMode === 'add') {
                this.auxiliaryService.addAccount(this.accountsForm.value);
            } else {
                this.auxiliaryService.editAccount(this.accountsForm.value);
            }
        }
    }

    // delete account
    deleteAccount() {
        this.confirmationService.confirm({
            key: 'accounts',
            message: `Are you sure you want to delete account ?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.auxiliaryService.deleteAccount(this.selectedAccount);
            },
        });
    }

    // close dialog
    closeDialog() {
        this.submitted = false;
        this.accountsForm.reset({
            is_customer: 1,
            is_bank: 0,
            is_employee: 0,
            is_supplier: 0,
        });
        this.auxiliaryService.dialogVisible.next(false);
    }
}
