import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { AccountingHomeComponent } from './accounting-home/accounting-home.component';
import { ChartOfAccountsComponent } from './chart-of-accounts/chart-of-accounts.component';
import { JournalVouchersComponent } from './journal-vouchers/journal-vouchers.component';
import { JournalItemsComponent } from './journal-items/journal-items.component';
import { AccountsComponent } from './accounts/accounts.component';

const routes: Routes = [
    {
        path: '', component: AccountingHomeComponent, children: [
            {
                path: 'chart', data: {
                    breadcrumb: 'Chart of Accounts'
                }, component: ChartOfAccountsComponent
            },
            {
                path: 'journal-vouchers', data: {
                    breadcrumb: 'Journal Vouchers'
                }, component: JournalVouchersComponent
            },
            {
                path: 'journal-items', data: {
                    breadcrumb: 'Journal Items'
                }, component: JournalItemsComponent
            },
            { path: 'accounts', data: { breadcrumb: 'Auxiliary Accounts' }, component: AccountsComponent },
            { path: '**', redirectTo: '/accounting/chart' }
        ]
    }
];

@NgModule({
    imports: [RouterModule.forChild(routes)],
    exports: [RouterModule]
})
export class AccountingRoutingModule { }
